module Top;
    logic [3:0] q[$], r[$], m[$];
    int i[$];
    initial begin
        q = '{4'b1x00, 4'd3, 4'b1x00, 4'bzzzz, 4'd3, 4'bzzzz, 4'b1z00};
        r = q.unique;
        i = q.unique_index;
        $display("unique size=%0d index size=%0d", r.size(), i.size());
        m = r.find with (item === 4'b1x00);
        $display("assigned find size=%0d operand size=%0d", m.size(), r.find with (item === 4'b1x00).size());
    end
endmodule
